/// <summary>
/// designed by AVANADE
/// </summary>
class AVAQuickCopyController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    super(classStr(AVAQuickCopyService), methodStr(AVAQuickCopyService, process), SysOperationExecutionMode::Synchronous);
}

public static AVAQuickCopyController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAQuickCopyController controller;
    controller = new AVAQuickCopyController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVAQuickCopyController controller;
    SysOperationStartResult sysOperationStartResult;
    AVAQuickCopyContract dataContract;
    //Set recordSet;
    RecordSortedList recordsortedList = new RecordSortedList(tableNum(SalesQuotationLine));
    SalesQuotationLine salesQuotationLine;
    MultiSelectionHelper multiselectionHelper;

    controller = AVAQuickCopyController::construct();
    controller.parmArgs(_args);

    if (_args && _args.caller() is FormRun)
    {
        //recordSet = new Set(Types::Record);
        recordsortedList.sortOrder(fieldNum(SalesQuotationLine, KCS_QLLVPosition), fieldNum(SalesQuotationLine, KCS_QLInternalPosition));
        multiselectionHelper = MultiSelectionHelper::createFromCaller(_args.caller());



        salesQuotationLine = multiselectionHelper.getFirst();
        while (salesQuotationLine)
        {
            //recordSet.add(salesQuotationLine);
            recordsortedList.ins(salesQuotationLine);

            salesQuotationLine = multiselectionHelper.getNext();
        }
    }

    dataContract = controller.getDataContractObject();
    if (dataContract is AVAQuickCopyContract)
    {
        //dataContract.parmRecordCon(recordSet.pack());
        dataContract.parmRecords(recordsortedlist);
    }

    sysOperationStartResult = controller.startOperation();

    if (_args && _args.caller() is FormRun)
    {
        FormRun                 callerFormRun = _args.caller() as FormRun;
        FormDataSource          quotLine_DS = callerFormRun.dataSource('SalesQuotationLine');    

        if (quotLine_DS)
        {
            quotLine_DS.executeQuery();
        }
    }
}

public boolean parmShowDialog(boolean _showDialog = showDialog)
{    
    return false;
}
